use crate::domains::rust_perf::PerfRule;

/// Data table, not logic — grows with distillation batches.
#[allow(clippy::too_many_lines)]
pub(super) fn entries() -> Vec<PerfRule> {
    vec![
        // ── dispatch: N consumers advance the SAME scalar every step →
        // host mirror + one shared array + a one-time equivalence
        // verdict, instead of N tiny device ops ───────────────────────
        // Source: LayerCacheV2.swift (the host position-offsets doc +
        // verdict log line).
        PerfRule {
            rule_id: "host-mirror-shared-scalar-advance-one-time-verdict".to_string(),
            name: "when N consumers (layers) each advance the SAME small scalar state by a uniform host-known delta every step (position offsets +L), keep a host mirror advanced at the same code sites, materialize ONE shared array per step for all consumers, and gate with a one-time device-vs-host equivalence verdict on first advance — match ⇒ host path for the process; mismatch ⇒ device op kept forever".to_string(),
            category: "dispatch".to_string(),
            buggy_code: "pub struct LayerOffsets {\n    offsets: Vec<u64>,\n}\n\nimpl LayerOffsets {\n    // One tiny device op PER LAYER per step: 16 one-element launches\n    // per verify window of the 27B, all advancing the same +L.\n    pub fn advance_per_layer(&mut self, layers: usize, base: u64, l: u64) -> Vec<u64> {\n        let mut out = Vec::with_capacity(layers);\n        for _ in 0..layers {\n            out.push(base + l); // one device add each\n        }\n        self.offsets = out.clone();\n        out\n    }\n}".to_string(),
            fixed_code: "pub struct LayerOffsets {\n    offsets: Vec<u64>,\n    verified_host_path: bool,\n}\n\nimpl LayerOffsets {\n    // The mirror is advanced at EVERY site the device array would be\n    // rebuilt (single-source-of-truth invariant), materialized ONCE per\n    // step, and identity-shared by all consumers. The first advance\n    // compares against the device add: match ⇒ host path forever;\n    // mismatch ⇒ the device op is kept forever (fail-safe).\n    pub fn advance_shared(&mut self, layers: usize, base: u64, l: u64, device_value: Option<u64>) -> &[u64] {\n        let shared = base + l;\n        if !self.verified_host_path {\n            self.verified_host_path = device_value == Some(shared);\n        }\n        if self.verified_host_path {\n            self.offsets.clear();\n            self.offsets.resize(layers, shared);\n        } else if let Some(dv) = device_value {\n            self.offsets.clear();\n            self.offsets.resize(layers, dv);\n        }\n        &self.offsets\n    }\n}".to_string(),
            context_notes: Some("NotBenchable-by-domain (the win is launch-count elimination inside a framework's command-buffer machinery — a Rust microbench would be decorative; the Batch-135 io-annotation class). SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ 831fae7, LayerCacheV2.swift, verbatim): 'The advanced `positionOffsets` of an attention layer's step, built from a host copy advanced by the same `+ L` instead of by an on-device add per layer (16 one-element launches per verify window of the 27B). The host' + the verdict log line '\"mlxfast host position offsets: first advance equals the device add; host copy\\n\"'. TWO LOAD-BEARING HALVES: (1) the mirror must be written at every site the device array is rebuilt (a mirror advanced at fewer sites diverges silently — the one-time verdict cannot catch a later site-specific drift); (2) the verdict is ONE-TIME by design — match ⇒ host path for the process, mismatch ⇒ device path forever (fail-safe). Anti-regimes: non-uniform per-row deltas (the rectangularity premise — 'L is uniform across every bound row'); values that depend on device-only data (not host-derivable); a consumer that could read the array mid-graph AFTER a shape-dependent divergence — the one-time verdict would not catch it (the residual risk is the honest cost, mitigated only by the same-site mirror discipline). Distinct from derived-scalar-host-computed-in-uniform (gpu_04 — a STATIC config scalar shipped once as a uniform; this is a RUNNING counter advanced per step, shared across N consumers, with a runtime verdict). Cite: @ 831fae7 — LayerCacheV2.swift L289-291 + L315; Batch 182 / Plan 177 / Research 216.".to_string()),
            // Not benchable: launch-count win is framework-specific.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
        // ── complexity: prompt-continuation draft override with the
        // MEASURED 16-token floor ─────────────────────────────────────
        // Source: CBv2PromptLookupDraft.swift (the measured-floor doc).
        PerfRule {
            rule_id: "prompt-continuation-draft-override-measured-min-match".to_string(),
            name: "when committed output repeats a span of the prompt, the tokens that followed that span are already known: replace ONLY the draft ids when a UNIQUE prompt span of >= minimumMatch tokens matches the committed suffix (ambiguity at a length is SKIPPED, never guessed), SKIP the drafter block on the round after a from-prompt proposal (look the continuation up first; run the drafter only on a miss), and splice along the prompt span in the early rounds — the target still verifies everything".to_string(),
            category: "complexity".to_string(),
            buggy_code: "pub struct Drafter {\n    min_match: usize, // a guessed floor: short matches \"help\"\n}\n\nimpl Drafter {\n    // Rank-merging the n best matches at n = 2..4: replaces CORRECT\n    // drafter tokens with prompt continuations and ADDS rounds.\n    pub fn propose(&self, committed: &[u32], prompt: &[u32]) -> Vec<u32> {\n        let mut best_len = 0usize;\n        for n in 2..5 {\n            if committed.len() >= n && ends_with_suffix(committed, &prompt[..n]) {\n                best_len = best_len.max(n);\n            }\n        }\n        let start = committed.len();\n        prompt[start..(start + best_len).min(prompt.len())].to_vec()\n    }\n}\n\nfn ends_with_suffix(committed: &[u32], suffix: &[u32]) -> bool {\n    committed.ends_with(suffix)\n}".to_string(),
            fixed_code: "pub struct Drafter {\n    // The MEASURED floor: a rank-merge at n = 2..4 replaced correct\n    // drafter tokens and added rounds (12 -> 15); a UNIQUE 16-token\n    // match (floor 8) is the minimum used. Ambiguity at a length is\n    // skipped, never guessed.\n    min_match: usize,\n}\n\nimpl Drafter {\n    pub fn propose(&self, committed: &[u32], prompt: &[u32]) -> Vec<u32> {\n        // Longest unique suffix match only; skip on ambiguity.\n        let mut best_len = 0usize;\n        for n in (self.min_match..=committed.len()).rev() {\n            if committed.ends_with(&prompt[..n]) && is_unique_at(prompt, n) {\n                best_len = n;\n                break;\n            }\n        }\n        if best_len < self.min_match {\n            return Vec::new(); // the real drafter block runs instead\n        }\n        let start = committed.len();\n        prompt[start..(start + 8).min(prompt.len())].to_vec()\n    }\n}\n\nfn is_unique_at(_prompt: &[u32], _n: usize) -> bool {\n    true\n}".to_string(),
            context_notes: Some("NotBenchable-by-domain (the win is model/prompt-dependent acceptance rate; a Rust microbench of the suffix scan would measure the wrong thing — the Batch-135 io-annotation class). SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ 831fae7, CBv2PromptLookupDraft.swift, verbatim): 'Short matches are not used. A rank-merge at n = 2...4 replaced correct drafter tokens and added rounds (9ac82eeb, 12 rounds -> 15). A unique' + 'drafter weight read for sixteen rows) produces a proposal nobody uses.' + 'those rows alone), and the next block that runs absorbs them all.' THE FOUR DECISION HALVES: (1) override ONLY the draft ids — the target still verifies everything; (2) drafter-SKIP on the round after a from-prompt proposal — do not build the next block before the readback; the skipped round's committed context rows stay pending in the drafter state and the next real block absorbs them ('layer K/V are a function of those rows alone — correctness preserved'); (3) early rounds use an on-device-scored splice (the drafter's ids are never read on the host; the lookup overlaps the host finalize); (4) interaction — a prompt-quoted row does not participate in draft-before-readback speculation, and the verify is flagged to submit sooner (no ~6 ms block queued ahead). MEASURED FLOOR: minimumMatch 16 (floor 8, env-tunable) — the negative result at n=2..4 is the load-bearing evidence, never a uniform-gain claim (acceptance-rate dependent). Anti-regimes: short matches (measured regression); ambiguous continuations (skip, never guess); non-prompt-first workloads (pure chat without quoting — the lookup is a cheap-but-nonzero host suffix scan per round); depth > 256 (the splice's fused path caps). KINSHIP: the corpus touches prompt-lookup only as a source-reported context rider inside gdn-transition-replay-log-commit-many (gpu_08: the cinference 'verify draft trees with prompt-lookup chains' 144.0 vs 100.8 tok/s) — the MECHANISM (override + skip + splice + measured floor) has no rule; that rider is the cross-engine confirmation. Distinct from staged-append-rollback-lifo-retry-blocks (gpu_08, allocator-level rollback). Cite: @ 831fae7 — CBv2PromptLookupDraft.swift L12-13 + L40 + L46; Batch 182 / Plan 177 / Research 216.".to_string()),
            // Not benchable: acceptance-rate dependent.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
        // ── complexity (measurement honesty #6): the ADOPTION side —
        // kernel-variant selection is adjudicated on WHOLE WORKLOAD
        // ROUNDS, interleaved, never on synthetic micro-bursts ───────
        // Source: Qwen35MTPTopTwo.swift (the in-situ trial doc + the
        // pinned constants).
        PerfRule {
            rule_id: "whole-round-in-situ-adoption-trial".to_string(),
            name: "kernel-variant adoption decisions must be adjudicated on whole workload rounds, interleaved (first round discarded; rounds > 1.5x their arm's median dropped; adopt only if the challenger's median beats by > 0.5% with >= 4 kept rounds; correctness-free because every candidate passed the bitwise self-test) — a 0.5-0.7 ms timing burst never reaches the GPU clock state of the real decode window and MISPICKS".to_string(),
            category: "complexity".to_string(),
            buggy_code: "pub struct KernelChoice {\n    name: &'static str,\n}\n\n// Burst adjudication: each candidate is timed in one synthetic 0.5 ms\n// burst; the fastest burst wins the dispatch table. The bursts never\n// reach the clock state of the real decode window, so they mispick.\npub fn pick_by_burst(candidates: &[KernelChoice], burst_us: &[u64]) -> usize {\n    let mut best = 0usize;\n    for (i, t) in burst_us.iter().enumerate() {\n        if *t < burst_us[best] {\n            best = i;\n        }\n    }\n    let _ = &candidates[best];\n    best\n}".to_string(),
            fixed_code: "pub struct KernelChoice {\n    name: &'static str,\n}\n\nconst ADOPT_MARGIN_PCT: f64 = 0.5;\nconst OUTLIER_FACTOR: f64 = 1.5;\nconst MINIMUM_ROUNDS: usize = 4;\n\n// Whole-round in-situ trial: candidates run in turn on REAL workload\n// rounds of the load-time warm, interleaved, first round discarded,\n// outlier rounds (> 1.5x their arm's median) dropped, adopted only on\n// a > 0.5% median win with >= 4 kept rounds. Adoption is\n// correctness-free: every candidate passed the bitwise self-test, so\n// the rounds and their tokens are the same whichever runs.\npub fn pick_by_rounds(\n    candidates: &[KernelChoice],\n    round_us: &[Vec<u64>], // per-candidate kept round times\n) -> usize {\n    let medians: Vec<f64> = round_us\n        .iter()\n        .map(|r| {\n            let mut s: Vec<f64> = r.iter().map(|t| *t as f64).collect();\n            s.sort_by(|a, b| a.total_cmp(b));\n            s[s.len() / 2]\n        })\n        .collect();\n    let mut best = 0usize;\n    for (i, m) in medians.iter().enumerate() {\n        if medians[best] > m * (1.0 + ADOPT_MARGIN_PCT / 100.0)\n            && round_us[i].len() >= MINIMUM_ROUNDS\n        {\n            best = i;\n        }\n    }\n    let _ = (&candidates[best], OUTLIER_FACTOR);\n    best\n}".to_string(),
            context_notes: Some("NotBenchable decision-content (the fix IS measurement methodology; adjudicating the adjudicator with a microbench is the same category error it names). SOURCE-REPORTED (Layr-Labs/mlxfast-bonsai2-27b-engine @ 831fae7, Qwen35MTPTopTwo.swift, verbatim): 'The in-situ choice of the verify int8 kernels: candidate choices (shortlisted by the synthetic self-test and timing at load) run in turn on real speculative rounds of the load-time engine warm, and a candidate replaces the record's pick only when its median round beats the record's pick's by more than 0.5 %. The synthetic timing streams each kernel for 0.5-0.7 ms bursts in which the GPU never reaches the clock state of the decode window, so it mispicks; a whole round does' + the pinned constants ('A candidate must beat the record's pick by more than this. static let adoptMargin = 0.005', 'static let stage2Slack = 0.02', 'Rounds above this multiple of their candidate's median are dropped. static let outlierFactor = 1.5', 'A candidate is adopted only with at least this many kept rounds. static let minimumRounds = 4'). THE FULL MECHANISM: roundBoundary() at the top of every block proposal/adopted block (one static bool check when idle); round time = host time boundary-to-boundary; the toggle installed at a boundary is what the next graph build reads; interleaved arms; FIRST ROUND DISCARDED (seed/compilation pollution); rounds > 1.5x their arm's median dropped; >= 4 kept rounds floor. SUB-ARM (same infra): per-shape selection via an L18 orthogonal array over per-shape factors — each production shape is a factor whose levels are the record kernel + the two fastest candidates; balanced-array means give the additive model's least-squares per-shape effects, then stage 2 ranks mixes (the construct-once dispatch table, measured per box at load — the immutable-static-map-filter-selection B179 sibling on the measurement half). Anti-regimes: one-shot processes (the probe cost never amortizes — run the trial inside the deferred load warm only); shapes not seen in production (the per-shape factors ARE the real production shapes). FAMILY: the measurement-honesty family's ADOPTION member — B177 aa-control-prices-the-fidelity-instrument prices the COMPARATOR, B181 seed-warm-the-scored-seam warms the SEAM, this decides the MEASUREMENT UNIT and the FLIP THRESHOLD for per-box kernel selection. Cite: @ 831fae7 — Qwen35MTPTopTwo.swift L3100-3106 + L3200-3208; Batch 182 / Plan 177 / Research 216.".to_string()),
            // Not benchable: the fix IS measurement methodology.
            #[cfg(feature = "rust_perf_bench")]
            bench_spec: None,
        },
    ]
}
